import { Product } from '@/data/products';
import { useAuthStore } from '@/store/useAuthStore';

export interface Category {
  id: string;
  name: string;
  slug: string;
  description?: string;
  is_active: boolean;
}

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:8000';

const getAuthHeader = (): Record<string, string> => {
  const token = useAuthStore.getState().token;
  return token ? { 'Authorization': `Bearer ${token}` } : {};
};

const mapToFrontend = (data: any): Product => ({
  id: data.id,
  name: data.name,
  slug: data.slug,
  price: data.price,
  description: data.description,
  imageUrl: data.image_url,
  category: data.category,
  weightOptions: data.weight_options || [],
  parts: data.parts || [],
});

const mapToBackend = (data: Partial<Product>): any => {
  const result: any = { ...data };
  if (data.imageUrl !== undefined) {
    result.image_url = data.imageUrl;
    delete result.imageUrl;
  }
  if (data.weightOptions !== undefined) {
    result.weight_options = data.weightOptions;
    delete result.weightOptions;
  }
  return result;
};

export const getProducts = async (): Promise<Product[]> => {
  try {
    const res = await fetch(`${API_BASE_URL}/api/v1/products/`, {
      cache: 'no-store'
    });
    if (!res.ok) throw new Error('Failed to fetch products');
    const data = await res.json();
    return data.map(mapToFrontend);
  } catch (error) {
    console.error(error);
    return [];
  }
};

export const getProductBySlug = async (slug: string): Promise<Product | undefined> => {
  try {
    const products = await getProducts();
    return products.find((p) => p.slug === slug);
  } catch (error) {
    console.error(error);
    return undefined;
  }
};

export const uploadImage = async (file: File): Promise<string> => {
  const formData = new FormData();
  formData.append('file', file);

  const res = await fetch(`${API_BASE_URL}/admin/upload`, {
    method: 'POST',
    headers: { ...getAuthHeader() },
    body: formData,
  });
  if (!res.ok) throw new Error('Failed to upload image');
  const data = await res.json();
  return `${API_BASE_URL}${data.imageUrl}`;
};

export const createProduct = async (product: Omit<Product, 'id'>): Promise<Product> => {
  const res = await fetch(`${API_BASE_URL}/admin/products`, {
    method: 'POST',
    headers: { 
      'Content-Type': 'application/json',
      ...getAuthHeader()
    },
    body: JSON.stringify(mapToBackend(product)),
  });
  if (!res.ok) throw new Error('Failed to create product');
  const data = await res.json();
  return mapToFrontend(data);
};

export const updateProduct = async (slug: string, productData: Partial<Product>): Promise<Product | undefined> => {
  const product = await getProductBySlug(slug);
  if (!product) throw new Error('Product not found');

  const res = await fetch(`${API_BASE_URL}/admin/products/${product.id}`, {
    method: 'PUT',
    headers: { 
      'Content-Type': 'application/json',
      ...getAuthHeader()
    },
    body: JSON.stringify(mapToBackend(productData)),
  });
  if (!res.ok) throw new Error('Failed to update product');
  const data = await res.json();
  return mapToFrontend(data);
};

export const deleteProduct = async (slug: string): Promise<boolean> => {
  const product = await getProductBySlug(slug);
  if (!product) return false;

  const res = await fetch(`${API_BASE_URL}/admin/products/${product.id}`, {
    method: 'DELETE',
    headers: { ...getAuthHeader() },
  });
  return res.ok;
};

// ── Categories API ─────────────────────────────────────────────────────────

export const getCategories = async (): Promise<Category[]> => {
  try {
    const res = await fetch(`${API_BASE_URL}/api/v1/categories`, {
      cache: 'no-store'
    });
    if (!res.ok) throw new Error('Failed to fetch categories');
    return await res.json();
  } catch (error) {
    console.error(error);
    return [];
  }
};

export const createCategory = async (category: Omit<Category, 'id' | 'created_at' | 'updated_at'>): Promise<Category> => {
  const res = await fetch(`${API_BASE_URL}/admin/categories`, {
    method: 'POST',
    headers: { 
      'Content-Type': 'application/json',
      ...getAuthHeader()
    },
    body: JSON.stringify(category),
  });
  if (!res.ok) throw new Error('Failed to create category');
  return await res.json();
};

export const updateCategory = async (id: string, categoryData: Partial<Category>): Promise<Category> => {
  const res = await fetch(`${API_BASE_URL}/admin/categories/${id}`, {
    method: 'PUT',
    headers: { 
      'Content-Type': 'application/json',
      ...getAuthHeader()
    },
    body: JSON.stringify(categoryData),
  });
  if (!res.ok) throw new Error('Failed to update category');
  return await res.json();
};

export const deleteCategory = async (id: string): Promise<boolean> => {
  const res = await fetch(`${API_BASE_URL}/admin/categories/${id}`, {
    method: 'DELETE',
    headers: { ...getAuthHeader() },
  });
  return res.ok;
};
